/* Light theme — parametric values (multiplier, subtractor, saturation, neutralSaturation)
   are now carried in the theme's overrides field and applied as inline styles by ThemeStore.
   No component-level overrides needed for light. */

/* ===== ELEMENTS OVERRIDES ===== */

/*
  The tooltip override that used to be here is gone, and it had stopped working long before it was
  removed. It painted `neutral-100` with `color: black` — written when the ramp was HSL and that step
  was a near-white, to undo a tooltip hardcoded to `#222`. Under the OKLCH ramp `neutral-100` in this
  theme's dark polarity resolves to L 18.4%, so it was near-black text on a near-black chip, and an
  outer-tree `::part` rule beats the shadow tree's own — so it won, silently, in the one theme that
  looked like it had been thought about.

  Nothing replaces it. `surfaceInverse` is now measured from the page rather than pinned, which lands
  this theme's tooltip at L 9.7% against a page of 18.7%, and `onInverse` is derived against that.
  A theme-level override here would be the same mistake a third time.
*/

[data-we-theme='black'] we-menu-item::part(base) {
  margin-top: var(--we-space-100);
  margin-left: var(--we-space-400);
  margin-right: var(--we-space-400);
  border-radius: 6px;
}

[data-we-theme='retro'] {
  --we-scrollbar-thumb-box-shadow:
    inset -1px -1px #0a0a0a, inset 1px 1px #fff, inset -2px -2px grey, inset 2px 2px #dfdfdf;
  --we-scrollbar-thumb-background: #dfdfdf;
  --we-scrollbar-background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg width='2' height='2' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M1 0H0v1h1v1h1V1H1V0z' fill='silver'/%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M2 0H1v1H0v1h1V1h1V0z' fill='%23fff'/%3E%3C/svg%3E");
  --we-scrollbar-width: 16px;
  --we-scrollbar-thumb-border-radius: 0;
}

[data-we-theme='retro'] we-modal::part(base) {
  position: relative;
  background: silver;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
  padding: 0;
}

[data-we-theme='retro'] we-modal::part(close-button) {
  top: 10px;
  right: 10px;
  padding: var(--we-space-200);
  width: var(--we-size-sm);
  height: var(--we-size-sm);
  background: silver;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* A Win95 title bar wants a `header` part on we-modal. There isn't one — the element renders
   backdrop, base, close-button-wrapper and a default slot, and nothing else — so the rule that
   used to sit here never matched anything. Removing it changes no pixels. Restoring the intent
   means adding the part to the primitive, which is a modal API change, not a theme fix. */

[data-we-theme='retro'] we-switch::part(thumb) {
  border-radius: 0;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
}

[data-we-theme='retro'] we-switch::part(track) {
  border-radius: 0;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
}

[data-we-theme='retro'] we-avatar::part(base) {
  border-radius: 0;
  border: 0;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
}

[data-we-theme='retro'] we-avatar::part(img) {
  border-radius: 0;
}

[data-we-theme='retro'] we-button::part(base) {
  background: silver !important;
  color: #222 !important;
  border: 0 !important;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
}

[data-we-theme='retro'] we-button[disabled]::part(base) {
  text-shadow: 1px 1px 0 #fff;
}

[data-we-theme='retro'] we-button::part(base):active {
  box-shadow:
    inset -1px -1px #fff,
    inset 1px 1px #0a0a0a,
    inset -2px -2px #dfdfdf,
    inset 2px 2px grey;
}

[data-we-theme='retro'] we-button[square]::part(base) {
  border-radius: 0;
}

[data-we-theme='retro'] we-tabs::part(base) {
  background: none;
  border: 0;
}

[data-we-theme='retro'] we-tabs::part(base)::before {
  content: none;
}

[data-we-theme='retro'] we-menu::part(base) {
  background: var(--we-color-neutral-100);

  /* Silver is not a role, so it stays here rather than in components.menu.border. */
  border-color: silver;
}

[data-we-theme='retro'] we-menu-group::part(summary) {
  padding-left: var(--we-space-300);
}

[data-we-theme='retro'] we-menu-group::part(content) {
  border-left: 1px dotted grey;
  margin-left: var(--we-space-500);
}

[data-we-theme='retro'] we-menu-item::part(base) {
  position: relative;
}

[data-we-theme='retro'] we-menu-item::part(base)::after {
  position: absolute;
  content: '';
  display: block;
  left: 0;
  width: 15px;
  height: 1px;
  border-top: 1px dotted grey;
}

[data-we-theme='retro'] we-tab::part(base) {
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
}

[data-we-theme='retro'] we-input::part(base) {
  background: white;
  border: 0;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
}

[data-we-theme='retro'] we-input::part(base):focus-within {
  border: 0;
  box-shadow:
    inset -1px -1px #0a0a0a,
    inset 1px 1px #fff,
    inset -2px -2px grey,
    inset 2px 2px #dfdfdf;
}

[data-we-theme='cyberpunk'] we-text[variant^='heading'] {
  display: block;
  position: relative;
  animation-name: glitched;
  animation-duration: 3s;
  animation-iteration-count: infinite;
  animation-direction: reverse;
  animation-timing-function: ease-out;
}

[data-we-theme='cyberpunk'] we-button::part(base) {
  clip-path: polygon(-15px 0%, calc(100% + 15px) 0%, calc(100% + 15px) 100%, 20px 100%, -15px calc(100% - 35px));
}

[data-we-theme='cyberpunk'] we-button::part(base):hover {
  clip-path: none;
}

[data-we-theme='cyberpunk'] we-button:hover {
  display: inline-block;
  animation-name: glitched;
  animation-duration: 2s;
  animation-iteration-count: infinite;
  animation-direction: reverse;
  animation-timing-function: ease-out;
}

[data-we-theme='cyberpunk'] we-menu-item::part(base) {
  margin-top: var(--we-space-100);
  margin-left: var(--we-space-300);
  margin-right: 0;
  clip-path: polygon(90% 0, 0 0, 0 50%, 5% 100%, 0% 100%, 100% 100%, 100% 0%);
}

[data-we-theme='cyberpunk'] we-tab::part(base) {
  clip-path: polygon(87% 0, 0 0, 0 50%, 13% 100%, 88% 100%, 100% 100%, 99% 16%);
}

[data-we-theme='cyberpunk'] we-input::part(base) {
  height: 60px;
  font-size: 16px;
  border: 10px solid var(--we-color-accent-500);
  border-left: 2px solid var(--we-color-accent-500);
  border-right: 2px solid var(--we-color-accent-500);
  border-bottom: 10px solid var(--we-color-accent-500);
  border-color: var(--we-color-accent-200);
  clip-path: polygon(
    0 5px,
    5px 0,
    calc(60% - 5px) 0,
    60% 5px,
    100% 5px,
    100% calc(100% - 5px),
    calc(100% - 5px) calc(100% - 3px),
    calc(80% - 3px) calc(100% - 3px),
    calc(80% - 5px) calc(100% - 0px),
    0 calc(100% - 0px),
    0% calc(100% - 0px)
  );
}

[data-we-theme='cyberpunk'] we-input::part(base):focus-within {
  border-color: var(--we-color-accent-500);
}

[data-we-theme='cyberpunk'] we-text[variant^='heading']::after {
  display: block;
  content: '';
  width: 100%;
  bottom: -10px;
  left: 0;
  height: 10px;
  clip-path: polygon(0 0, 85px 0, 90px 5px, 100% 5px, 100% 6px, 85px 6px, 80px 10px, 0 10px);
  background: var(--we-color-accent-500);
}

@keyframes glitched {
  0% {
    transform: skew(-15deg);
    left: -4px;
  }

  10% {
    transform: skew(-15deg);
    left: -4px;
  }

  11% {
    transform: skew(0deg);
    left: 2px;
  }

  50% {
    transform: skew(0deg);
  }

  51% {
    transform: skew(5deg);
  }

  59% {
    transform: skew(5deg);
  }

  60% {
    transform: skew(0deg);
  }

  100% {
    transform: skew(0deg);
  }
}
